ON CONFLICT(uid) DO UPDATE SET source_list = excluded.source_list, name = excluded.name, name_normalized = excluded.name_normalized, addresses = excluded.addresses, federal_register_notice = excluded.federal_register_notice, license_requirement = excluded.license_requirement, license_policy = excluded.license_policy, start_date = excluded.start_date, source_url = excluded.source_url, last_updated = excluded.last_updated WHERE csl_entries.source_list IS NOT excluded.source_list OR csl_entries.name IS NOT excluded.name OR csl_entries.name_normalized IS NOT excluded.name_normalized OR csl_entries.addresses IS NOT excluded.addresses OR csl_entries.federal_register_notice IS NOT excluded.federal_register_notice OR csl_entries.license_requirement IS NOT excluded.license_requirement OR csl_entries.license_policy IS NOT excluded.license_policy OR csl_entries.start_date IS NOT excluded.start_date OR csl_entries.source_url IS NOT excluded.source_url;
WITH v(uid, alias, norm, typ) AS (VALUES ('17250', 'Gazprom PAO', 'GAZPROM', NULL),
