INSERT INTO csl_aliases (csl_id, alias, alias_normalized) SELECT e.id, v.alias, v.norm FROM v JOIN csl_entries e ON e.uid = v.uid WHERE NOT EXISTS (SELECT 1 FROM csl_aliases a WHERE a.csl_id = e.id AND a.alias = v.alias);
WITH v(uid, alias, typ) AS (VALUES ('17250', 'Gazprom PAO', NULL),
('17250', 'PJSC Gazprom', NULL),
('17250', 'Gazprom', NULL))
DELETE FROM csl_aliases WHERE id IN (SELECT a.id FROM csl_aliases a JOIN csl_entries e ON e.id = a.csl_id WHERE e.uid IN ('17250') AND NOT EXISTS (SELECT 1 FROM v WHERE v.uid = e.uid AND v.alias = a.alias));
